<script setup lang="ts">
import { computed,nextTick,onBeforeUnmount,onMounted,ref,watch } from "vue";
import { ask,err,isDemo,type Citation } from "./api";
import { askView } from "./ask-result";
import { assistantScope,type AssistantScope } from "./assistant-scope";
import { queryPlanFrom,type QueryPlan } from "./query-plan";
import { parseSse } from "./sse";
import { boundedHistory,exportConversation,loadActiveConversation,loadConversations,saveActiveConversation,saveConversations,storageState,type Attachment,type Conversation,type ConversationMessage,type StoredPlan } from "./conversation-store";
const categoryName:Record<string,string>={model_release:"模型发布",agent_tool:"智能体工具",framework_sdk:"框架与 SDK",research:"研究",product:"产品",industry:"产业"};
const open=ref(false),historyOpen=ref(false),conversations=ref<Conversation[]>([]),activeId=ref(""),running=ref(false),status=ref(""),returnFocus=ref<HTMLElement>(),panelWidth=ref(460),historyWidth=ref(220),atBottom=ref(true),expanded=ref("");
const clone=(x:AssistantScope):AssistantScope=>({label:x.label,snapshot:x.snapshot,filters:{...x.filters}}); const pendingScope=ref(clone(assistantScope)),activeScope=ref(clone(assistantScope)); let controller:AbortController|undefined,generation=0,ruleController:AbortController|undefined,ruleGeneration=0,timers:number[]=[];
const active=computed(()=>conversations.value.find(x=>x.id===activeId.value));const attachment=computed<Attachment|undefined>({get:()=>active.value?.attachment,set:v=>{if(active.value){active.value.attachment=v;touch(active.value);persist()}}});const messages=computed(()=>active.value?.messages||[]);const draft=computed({get:()=>active.value?.draft||"",set:v=>{if(active.value){active.value.draft=v;touch(active.value);persist()}}});const mode=computed<"demo"|"live">(()=>isDemo()?"demo":"live");
const scopeIssue=computed(()=>{const f=activeScope.value.filters;if(f.date_from&&f.date_to&&f.date_from>f.date_to)return "当前范围的起始日期晚于截止日期。";if(f.date_from&&f.date_to&&(Date.parse(f.date_to+"T00:00:00Z")-Date.parse(f.date_from+"T00:00:00Z"))/86400000+1>366)return "当前范围超过 366 天，请缩小范围后提问。";return ""});const scopeChanged=computed(()=>pendingScope.value.snapshot!==activeScope.value.snapshot||JSON.stringify(pendingScope.value.filters)!==JSON.stringify(activeScope.value.filters));
function id(){return crypto.randomUUID()}function titleFrom(question:string){return question.replace(/\s+/g," ").slice(0,24)||"新研究会话"}function touch(c:Conversation){c.updatedAt=Date.now()}function persist(){void saveConversations(conversations.value);void saveActiveConversation(activeId.value)}function create(){cancel();const now=Date.now(),c:Conversation={id:id(),title:"新研究会话",draft:"",createdAt:now,updatedAt:now,messages:[]};conversations.value=[c,...conversations.value];activeId.value=c.id;attachment.value=undefined;status.value="";persist()}function selectConversation(id:string){if(id===activeId.value)return;cancel();activeId.value=id;attachment.value=undefined;status.value="已切换会话；旧回答保留其提交时的范围。";persist()}
function openPanel(e:Event){returnFocus.value=e.currentTarget as HTMLElement;if(!active.value)create();open.value=true;void nextTick(()=>document.querySelector<HTMLTextAreaElement>(".assistant-composer textarea")?.focus())}function close(){cancel();open.value=false;void nextTick(()=>returnFocus.value?.focus())}function rename(){if(!active.value)return;const v=prompt("会话名称",active.value.title);if(v){active.value.title=v.trim()||active.value.title;touch(active.value);persist()}}function remove(){if(!active.value)return;cancel();conversations.value=conversations.value.filter(x=>x.id!==activeId.value);activeId.value=conversations.value[0]?.id||"";if(!active.value)create();persist()}function exportActive(){if(!active.value)return;const b=new Blob([exportConversation(active.value)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(b);a.download=active.value.title+".json";a.click();setTimeout(()=>URL.revokeObjectURL(a.href),0)}function applyCurrentScope(){activeScope.value=clone(pendingScope.value);status.value="已采用当前页面范围；下一次提问会使用它。"}
function append(m:ConversationMessage,c=active.value){if(!c)return;c.messages.push(m);touch(c);persist()}function cancel(){generation++;ruleGeneration++;controller?.abort();ruleController?.abort();timers.forEach(clearTimeout);timers=[];if(running.value&&active.value){const a=[...active.value.messages].reverse().find(x=>x.role==="assistant"&&x.status==="running");if(a){a.status="cancelled";a.text||="已取消，未自动重试。";touch(active.value);persist()}}running.value=false;status.value="已取消，未自动重试。"}function plan(v:unknown){const value=queryPlanFrom(v);return value?JSON.parse(JSON.stringify(value)) as StoredPlan:undefined}
function stream(){let control:ReadableStreamDefaultController<Uint8Array>;const emit=(v:string,t:number)=>timers.push(window.setTimeout(()=>control.enqueue(new TextEncoder().encode(v)),t));return new ReadableStream({start(c){control=c;emit('event: token\ndata: {"text":"这是"}\n\n',120);emit('event: token\ndata: {"text":"明确标注的模拟回答。[2]"}\n\n',300);emit('event: sources\ndata: {"items":[{"index":2,"title":"合成演示来源","source_url":"https://example.invalid/demo","quote_text":"合成段落摘录","paragraph_id":"demo-p-001"}]}\n\n',450);emit('event: done\ndata: {"scope_total":1,"retrieved_count":1,"summarized_count":1,"citation_count":1,"coverage":"complete","status":"completed"}\n\n',570);timers.push(window.setTimeout(()=>c.close(),620))},cancel(){timers.forEach(clearTimeout)}})}
async function submit(){const c=active.value,q=draft.value.trim();if(!c||!q||running.value||scopeIssue.value)return;const current=++generation,scope=clone(activeScope.value),requestMode=mode.value,target=attachment.value;draft.value="";const u:ConversationMessage={id:id(),role:"user",text:q,createdAt:Date.now(),scope:scope.snapshot,filters:{...scope.filters},mode:requestMode,attachment:target};append(u,c);if(c.title==="新研究会话")c.title=titleFrom(q);attachment.value=undefined;const a:ConversationMessage={id:id(),role:"assistant",text:"",createdAt:Date.now(),scope:scope.snapshot,filters:{...scope.filters},mode:requestMode,status:"running"};append(a,c);running.value=true;status.value=requestMode==="demo"?"模拟流：正在检索":"正在检索并汇总…";if(atBottom.value)void nextTick(scrollBottom);try{if(requestMode==="demo"){for await(const e of parseSse(stream(),(controller=new AbortController()).signal)){if(current!==generation||activeId.value!==c.id)return;if(e.event==="token"){a.text+=JSON.parse(e.data).text;if(atBottom.value)void nextTick(scrollBottom);}if(e.event==="sources")a.citations=JSON.parse(e.data).items as Citation[];if(e.event==="done"){a.metrics=JSON.parse(e.data);a.status="completed";status.value="模拟流已完成"}touch(c);persist()}}else{const response=await ask({question:q,filters:scope.filters,timezone:"Asia/Shanghai",answer_mode:"concise",client_request_id:id(),history:boundedHistory(c.messages,u.id),event_ids:target?[target.id]:undefined},(controller=new AbortController()).signal);if(current!==generation||activeId.value!==c.id)return;const v=askView(response);a.text=response.answer|| (response.answer_status==="no_answer"?"没有可回答的资料。":"");a.citations=v.citations;a.metrics=response;a.plan=plan(response);a.status=response.execution_status==="completed"?"completed":"error";if(a.status==="error")a.error={code:response.execution_status,message:v.status};status.value=v.status;touch(c);persist()}}catch(cause){if(current!==generation||activeId.value!==c.id)return;if((cause as Error).name==="AbortError"){a.status="cancelled";a.text||="已取消，未自动重试。"}else{const failure=err(cause);a.status="error";a.error={code:failure.code,message:failure.code==="CLARIFICATION_REQUIRED"?"附件与当前范围不一致。请移除标记为不在范围或未找到的附件，或调整范围后重试。":failure.message};a.plan=plan(cause);a.text=a.error.message}status.value=a.status==="cancelled"?"已取消，未自动重试。":a.error?.code||"请求失败";touch(c);persist()}finally{if(current===generation)running.value=false}}
function narrow(v:StoredPlan){const roles=v.entity_roles||[];return v.requires_clarification||!!v.free_text||!!v.filters.entity_ids?.length||(roles.length>0&&!(roles.includes("subject")&&roles.includes("product")))}function applyRulePlan(v:StoredPlan){if(scopeChanged.value){status.value="请先采用当前页面范围，再应用规则到当前总览。";return}if(narrow(v)){status.value="该解析包含无法由当前页面筛选完整表达的条件。";return}window.dispatchEvent(new CustomEvent("assistant-apply-plan",{detail:v.filters}));status.value="规则范围已应用到当前总览；请采用稳定范围后提问。"}async function planQuestion(){const q=draft.value.trim(), conversation=active.value;if(!q||!conversation)return;const conversationId=conversation.id,n=++ruleGeneration;ruleController?.abort();status.value="正在按问题解析筛选条件…";try{const response=await fetch("/api/v1/query-plan",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({question:q,filters:activeScope.value.filters,timezone:"Asia/Shanghai",client_request_id:id()}),signal:(ruleController=new AbortController()).signal});if(!response.ok)throw new Error("规则解析请求失败");const p=plan({query_plan_public:await response.json()});if(!p)throw new Error("规则解析结果无效");if(n!==ruleGeneration||activeId.value!==conversationId)return;append({id:id(),role:"assistant",text:"规则解析预览",createdAt:Date.now(),scope:activeScope.value.snapshot,filters:{...activeScope.value.filters},mode:mode.value,status:"completed",plan:p});status.value="已生成规则预览。"}catch(e){if(n===ruleGeneration&&(e as Error).name!=="AbortError")status.value=e instanceof Error?e.message:"规则解析失败"}}
function scrollBottom(){const e=document.querySelector<HTMLElement>(".assistant-messages");e?.scrollTo({top:e.scrollHeight,behavior:"smooth"});atBottom.value=true}function onMessageScroll(e:Event){const node=e.target as HTMLElement;atBottom.value=node.scrollHeight-node.scrollTop-node.clientHeight<30}function widths(){panelWidth.value=Math.min(innerWidth*.5,Math.max(340,Number.isFinite(panelWidth.value)?panelWidth.value:460));historyWidth.value=Math.max(0,Math.min(360,panelWidth.value-340,Number.isFinite(historyWidth.value)?historyWidth.value:220));try{localStorage.setItem("assistant-width",String(panelWidth.value));localStorage.setItem("history-width",String(historyWidth.value))}catch{storageState.failed=true}document.documentElement.style.setProperty("--assistant-width",panelWidth.value+"px")}function resize(e:PointerEvent,target:"panel"|"history"){const x=e.clientX,start=target==="panel"?panelWidth.value:historyWidth.value;const move=(p:PointerEvent)=>{const d=x-p.clientX;if(target==="panel")panelWidth.value=Math.min(innerWidth*.5,Math.max(340,start+d));else historyWidth.value=Math.max(0,Math.min(360,panelWidth.value-340,start-d));widths()};const up=()=>{window.removeEventListener("pointermove",move);window.removeEventListener("pointerup",up)};window.addEventListener("pointermove",move);window.addEventListener("pointerup",up)}function keyResize(e:KeyboardEvent,target:"panel"|"history"){if(!e.altKey||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const d=e.key==="ArrowLeft"?-20:20;if(target==="panel")panelWidth.value=Math.min(innerWidth*.5,Math.max(340,panelWidth.value+d));else historyWidth.value=Math.max(0,Math.min(360,panelWidth.value-340,historyWidth.value-d));widths()}
function focusCitation(message:string,index:number){expanded.value=message+":"+index;void nextTick(()=>document.getElementById("assistant-citation-"+message+"-"+index)?.focus())}function attach(e:Event){const d=(e as CustomEvent<Attachment>).detail;if(!d)return;if(!active.value)create();attachment.value=d;open.value=true;void nextTick(()=>document.querySelector<HTMLTextAreaElement>(".assistant-composer textarea")?.focus())}function validUrl(v:string){return /^https:\/\//i.test(v)}function onKey(e:KeyboardEvent){if(e.key==="Escape"&&open.value&&!e.defaultPrevented&&!document.querySelector("dialog[open]")){e.preventDefault();close()}}function trap(e:KeyboardEvent){if(e.key!=="Tab"||!matchMedia("(max-width:900px)").matches)return;const a=[...document.querySelectorAll<HTMLElement>("#global-assistant button,#global-assistant textarea,#global-assistant a")].filter(x=>!x.hasAttribute("disabled")),f=a[0],l=a.at(-1);if(!f||!l)return;if(e.shiftKey&&document.activeElement===f){e.preventDefault();l.focus()}else if(!e.shiftKey&&document.activeElement===l){e.preventDefault();f.focus()}}function mobile(){const v=open.value&&matchMedia("(max-width:900px)").matches;document.querySelector(".app-content main")?.toggleAttribute("inert",v);document.querySelector(".app-rail")?.toggleAttribute("inert",v)}
watch(assistantScope,s=>{pendingScope.value=clone(s);if(!running.value&&messages.value.length===0)activeScope.value=clone(s)},{deep:true,immediate:true});watch(open,v=>{document.documentElement.classList.toggle("global-assistant-open",v);mobile()});watch(panelWidth,widths);watch(historyOpen,v=>{if(v&&innerWidth>900&&panelWidth.value<520)panelWidth.value=Math.min(innerWidth*.5,520)});onMounted(async()=>{try{const savedPanel=Number(localStorage.getItem("assistant-width")),savedHistory=Number(localStorage.getItem("history-width"));panelWidth.value=Number.isFinite(savedPanel)&&savedPanel>0?Math.min(innerWidth*.5,savedPanel):460;historyWidth.value=Number.isFinite(savedHistory)&&savedHistory>=0?savedHistory:220}catch{storageState.failed=true}conversations.value=await loadConversations();const saved=await loadActiveConversation();activeId.value=conversations.value.some(x=>x.id===saved)?saved:conversations.value[0]?.id||"";widths();window.addEventListener("attach-event",attach as EventListener);document.addEventListener("keydown",onKey,true);window.addEventListener("resize",mobile)});onBeforeUnmount(()=>{cancel();window.removeEventListener("attach-event",attach as EventListener);document.removeEventListener("keydown",onKey,true);window.removeEventListener("resize",mobile);document.querySelector(".app-content main")?.removeAttribute("inert");document.querySelector(".app-rail")?.removeAttribute("inert");document.documentElement.classList.remove("global-assistant-open")})
</script>
<template><button class="assistant-trigger" data-testid="assistant-toggle" :aria-expanded="open" aria-controls="global-assistant" @click="openPanel">提问</button><aside v-show="open" id="global-assistant" class="assistant-panel assistant-workspace" data-testid="global-assistant" :style="{width:panelWidth+'px'}" :inert="!open" aria-label="全站研究助手" @keydown="trap"><button class="assistant-resizer" data-testid="assistant-resizer" aria-label="调整助手宽度（Alt 加方向键）" @pointerdown="resize($event,'panel')" @keydown="keyResize($event,'panel')"></button><section class="assistant-main"><header class="assistant-panel__header"><div><strong>研究助手</strong><p class="meta">{{ activeScope.snapshot }}</p></div><button class="assistant-close" @click="close">返回</button></header><p v-if="storageState.failed" class="error" role="alert">浏览器存储不可用，当前会话仅保存在内存中；仍可导出。</p><section class="assistant-scope"><p><strong>{{ activeScope.label }}</strong></p><p v-if="scopeChanged" class="meta">页面范围已变化；历史回答保留提交时的范围快照。</p><button v-if="scopeChanged" @click="applyCurrentScope">采用此页面的新范围</button></section><div v-if="messages.length" class="assistant-messages" data-testid="conversation-messages" @scroll="onMessageScroll"><article v-for="m in messages" :key="m.id" class="conversation-turn" data-testid="conversation-turn" :class="m.role"><p class="meta">{{ m.role==='user'?'你':'助手' }} · {{ m.scope }} · {{ m.mode==='demo'?'模拟数据':'服务数据' }}</p><p v-if="m.mode==='demo'&&m.role==='assistant'" class="demo">模拟流，仅用于演示。</p><p class="answer-body">{{ m.text }}</p><p v-if="m.status === 'cancelled' || m.status === 'interrupted'" class="meta">{{ m.status === 'cancelled' ? '已取消，未自动重试。' : '请求已中断，未自动重试。' }}</p><p v-if="m.metrics?.coverage === 'partial'" class="meta">覆盖不完整：答案仅基于部分匹配资料。</p><p v-if="m.attachment" class="meta">下一问依据：{{ m.attachment.title }}</p><p v-if="m.error" class="error" role="alert"><strong>{{m.error.code}}</strong>：{{m.error.message}}</p><section v-if="m.plan" class="query-plan assistant-plan" data-testid="query-plan"><h2>检索范围</h2><p>业务日期：{{m.plan.business_date}} · 时区：{{m.plan.timezone}}</p><p>分类：{{m.plan.filters.category?(categoryName[m.plan.filters.category]||m.plan.filters.category):'全部分类'}} · 日期：{{m.plan.filters.date_from||'不限'}} 至 {{m.plan.filters.date_to||'不限'}}（起止日期均包含）。</p><p>实体：{{m.plan.filters.entity_ids?.length?`${m.plan.filters.entity_match==='all'?'同时匹配':'任一匹配'} ${m.plan.filters.entity_ids.length} 个实体`:'未限定实体'}}</p><p v-if="m.plan.entity_roles?.length">实体角色：{{m.plan.entity_roles.map(x=>x==='subject'?'主体':'产品').join('、')}}</p><p v-if="m.plan.requires_clarification">需要澄清：{{m.plan.clarification_candidates.map(x=>x.label).join('、')}}</p><p v-if="m.plan.free_text">未理解限制：{{m.plan.free_text}}</p><p v-if="m.plan.history_turns_considered !== undefined" class="meta">已参考历史 {{m.plan.history_turns_considered}} 轮，其中用户问题 {{m.plan.history_user_turns_used||0}} 轮。</p><p v-if="m.plan.filters.event_ids?.length" class="meta">附加事件：{{m.plan.filters.event_ids.length}} 个。</p><ul v-if="m.plan.event_targets?.length" class="meta"><li v-for="target in m.plan.event_targets" :key="target.event_id">附件 {{target.title_zh||target.event_id}}：{{target.status==='matched'?'已纳入':target.status==='filtered_out'?'不在当前范围，可移除附件或调整范围':'未找到，可移除附件'}}</li></ul><ul v-if="m.plan.warnings.length"><li v-for="w in m.plan.warnings" :key="w">{{w}}</li></ul><button v-if="m.text==='规则解析预览'" @click="applyRulePlan(m.plan)">应用到总览</button></section><div v-for="c in m.citations" :key="m.id+'-'+c.index" class="evidence-item"><button :aria-expanded="expanded===m.id+':'+c.index" :aria-controls="'assistant-citation-'+m.id+'-'+c.index" @click="expanded=expanded===m.id+':'+c.index?'':m.id+':'+c.index">[{{c.index}}] {{c.title}}</button><blockquote v-if="expanded===m.id+':'+c.index" :id="'assistant-citation-'+m.id+'-'+c.index" tabindex="-1">{{c.quote_text||'无段落摘录'}}<footer class="meta">段落 {{c.paragraph_id||'未提供'}}</footer></blockquote><a v-if="validUrl(c.source_url)" :href="c.source_url" target="_blank" rel="noopener">打开来源</a></div><p v-if="m.metrics" class="meta tabular">完整匹配 {{m.metrics.scope_total}} · 取回 {{m.metrics.retrieved_count}} · 总结 {{m.metrics.summarized_count}} · 引用 {{m.metrics.citation_count}} · 覆盖：{{m.metrics.coverage}}</p></article><button v-if="!atBottom" @click="scrollBottom">回到最新消息</button></div><p v-else class="assistant-empty">输入问题开始研究；范围会随本轮记录。</p><div class="assistant-composer ask-question" data-testid="assistant-composer"><p v-if="attachment" class="assistant-attachment" data-testid="attached-event">下一问依据：{{attachment.title}} <button @click="attachment=undefined">移除</button></p><label>问题<textarea v-model="draft" rows="3" placeholder="输入需要核查的问题" /></label><p v-if="scopeIssue" class="error" role="alert">{{scopeIssue}}</p><div class="row"><button class="primary" :disabled="running||!draft.trim()||Boolean(scopeIssue)" @click="submit">发送</button><button :disabled="!draft.trim()" @click="planQuestion">按问题筛选</button><button v-if="running" @click="cancel">取消</button><button data-testid="history-toggle" :aria-expanded="historyOpen" @click="historyOpen=!historyOpen">历史</button><button data-testid="new-conversation" @click="create">新建</button></div><p class="meta" aria-live="polite">{{status}}</p></div></section><aside v-if="historyOpen" class="history-panel" aria-label="研究会话历史" data-testid="history-panel" :style="{width:historyWidth+'px'}"><button class="history-resizer" data-testid="history-resizer" aria-label="调整历史宽度（Alt 加方向键）" @pointerdown="resize($event,'history')" @keydown="keyResize($event,'history')"></button><button @click="rename">重命名</button><button v-for="x in conversations" :key="x.id" data-testid="history-item" :data-conversation-id="x.id" :class="{active:x.id===activeId}" @click="selectConversation(x.id)">{{x.title}}</button><div class="row"><button @click="remove">删除</button><button @click="exportActive">导出</button></div></aside></aside></template>
